    return super.describe() + " / " + this.minutes + " min";
  }
}

explanation:
new Session(minutes) initializes by assigning through the same setter, so invalid construction also fails. The getter reads the backing field; assigning this.minutes inside its own setter would recursively invoke that setter instead.
```javascript
class Session {
  constructor(minutes) { this.minutes = minutes; }
  get minutes() { return this._minutes; }
  set minutes(value) {
    if (!Number.isInteger(value) || value < 0 || value > 60) {
      throw new RangeError("minutes must be an integer from 0 to 60");
    }
    this._minutes = value;
  }
}
const session = new Session(10);
session.minutes = 20;
console.log(session.minutes);
try { session.minutes = -1; }
catch (error) { console.log(error instanceof RangeError); }
console.log(session.minutes);
```
Output: 20, true,20. The failed negative assignment does not replace the accepted value.

lessons.solution:
class Session {
  constructor(minutes) { this.minutes = minutes; }
  get minutes() { return this._minutes; }
  set minutes(value) {
    if (!Number.isInteger(value) || value < 0 || value > 60) {
      throw new RangeError("minutes must be an integer from 0 to 60");
    }
    this._minutes = value;
  }
}

explanation:
```javascript
class Counter {
  #value;
  constructor(initial) { this.#value = initial; }
  add(amount) { this.#value += amount; return this.#value; }
  read() { return this.#value; }
  static zero() { return new Counter(0); }
}
const first = Counter.zero();
const second = Counter.zero();
console.log(first.add(3));
console.log(second.read());
console.log(typeof first.zero);
```
Output: 3,0,undefined. Changing first does not change second. typeof first.zero is undefined because the static method is not an instance method. The constructor accepts an initial finite number; this focused exercise does not add input validation.

lessons.solution:
class Counter {
  #value;
  constructor(initial) { this.#value = initial; }
  add(amount) { this.#value += amount; return this.#value; }
  read() { return this.#value; }
  static zero() { return new Counter(0); }
}

explanation:
makeSettings takes no arguments and returns the outer frozen object. Object.getOwnPropertyDescriptor reads one own property’s descriptor, or undefined if missing; its writable flag reports the rule. The "use strict" directive makes assigning the read-only version throw TypeError instead of silently doing nothing.
```javascript
"use strict";
function makeSettings() {
  const settings = {theme: {dark: false}};
  Object.defineProperty(settings, "version", {
    value: 1, writable: false, enumerable: true, configurable: false
  });
  return Object.freeze(settings);
}
const settings = makeSettings();
console.log(Object.getOwnPropertyDescriptor(settings, "version").writable);
try { settings.version = 2; }
catch (error) { console.log(error instanceof TypeError); }
settings.theme.dark = true;
console.log(settings.version, settings.theme.dark);
```
Output: false; true; 1 true. The nested dark assignment still succeeds.

lessons.solution:
function makeSettings() {
  const settings = {theme: {dark: false}};
  Object.defineProperty(settings, "version", {
    value: 1, writable: false, enumerable: true, configurable: false
  });
  return Object.freeze(settings);
}

explanation:
```javascript
class LoadError extends Error {
  constructor(message, cause) {
    super(message, {cause});
    this.name = "LoadError";
  }
}
function readLabel(raw, events) {
  try {
    const data = JSON.parse(raw);
    if (typeof data?.label !== "string") {
      throw new TypeError("label must be text");
    }
    return data.label;
  } catch (cause) {
    throw new LoadError("Cannot load label", cause);
  } finally {
    events.push("finished");
  }
}
const events = [];
try { readLabel('{"label":7}', events); }
catch (error) { console.log(error.name, error.cause instanceof TypeError); }
console.log(events.join(","));
```
Output: LoadError true, then finished. The cause is the original TypeError object, not merely its text. This array event demonstrates finalization order; it does not acquire or close a real external resource.

lessons.solution:
class LoadError extends Error {
  constructor(message, cause) {
    super(message, {cause});
    this.name = "LoadError";
  }
}
function readLabel(raw, events) {
  try {
    const data = JSON.parse(raw);
    if (typeof data?.label !== "string") {
      throw new TypeError("label must be text");
    }
    return data.label;
  } catch (cause) {
    throw new LoadError("Cannot load label", cause);
  } finally {
    events.push("finished");
  }
}

explanation:
setActive(button,active) receives an existing button and Boolean, updates its attribute/class, and returns the token’s final state. querySelector("#toggle") returns the first matching element or null; this supplied markup guarantees a match.
```javascript
function setActive(button, active) {
  button.setAttribute("aria-pressed", String(active));
  return button.classList.toggle("active", active);
}
const button = document.querySelector("#toggle");
console.log(setActive(button, true));
console.log(button.getAttribute("aria-pressed"));
console.log(button.classList.contains("control"), button.classList.contains("active"));
console.log(setActive(button, false));
```
Output: true; true; true true; false. The second line is attribute text, even though it looks like the first line’s Boolean.

lessons.solution:
function setActive(button, active) {
  button.setAttribute("aria-pressed", String(active));
  return button.classList.toggle("active", active);
}

explanation:
A minimal failing case keeps only the data needed to expose a bug. The intended total of [5] is5, and the total of [] is0. This broken function parses and runs, but returns the wrong value: it is a logic/bounds defect, not a syntax error.
```javascript
function brokenTotal(values) {
  let total = 0;
  for (let i = 0; i <= values.length; i += 1) {
    total += values[i];
  }
  return total;
}
console.log(brokenTotal([5]));
console.log(Number.isNaN(brokenTotal([])));
```
Output: NaN then true. Number.isNaN(value) returns whether the value is the special numeric NaN, without converting strings.

For a one-item array the only valid index is0; length is1. The <= test permits an extra iteration at index1. Reading that missing entry gives undefined; adding it produces NaN. Trace the state before each update:
```javascript
const values = [5];
let total = 0;
for (let i = 0; i <= values.length; i += 1) {
  console.log(i, values[i]);
  total += values[i];
}
console.log(total);
```
Output: 0 5; 1 undefined; NaN. A debugger’s breakpoint/watch can help inspect the same state, but this scripted trace does not demonstrate an actual DevTools session.

The loop must stop when i equals length. Replacing <= with < avoids the nonexistent entry. Do not merely replace NaN with0 afterward: that would hide the defect and lose valid totals. totalValues receives a finite-number array and returns its sum without modifying it.
```javascript
function totalValues(values) {
  let total = 0;
  for (let i = 0; i < values.length; i += 1) {
    total += values[i];
  }
  return total;
}
console.log(totalValues([5]));
console.log(totalValues([]));
```
Output: 5 then0.

